def solve(n):
    # X = set of all (x, y)
    X = list(itertools.product(range(n), range(n)))

    # A set S is valid if for all p1, p2 in S, dist_inf(p1, p2) >= 2
    def is_valid(S):
        for p1, p2 in itertools.combinations(S, 2):
            if max(abs(p1[0] - p2[0]), abs(p1[1] - p2[1])) < 2:
                return False
        return True

    # F = {S subset X | S is valid and |S| >= 2}
    F = []
    for r in range(2, n*n + 1):
        for S in itertools.combinations(X, r):
            if is_valid(S):
                F.append(set(S))

    # D = {S1 ^ S2 | S1, S2 in F, S1 != S2}
    # We need a hitting set for D.
    # A set Q is a hitting set if for every d in D, d \cap Q is not empty.

    # Optimization: D can be large. But we only need to hit all d.
    # A set Q is a hitting set if for every d in D, there is some q in Q such that q in d.
    # This is equivalent to: for every S1, S2 in F, (S1 ^ S2) \cap Q != empty.

    # Let's find all S1 ^ S2.
    # Actually, we can find the minimal hitting set by checking all subsets of X? No, too many.
    # But we can find which x must be in Q.
    # x must be in Q if there exists S1, S2 in F such that S1 ^ S2 = {x}.

    must_have = set()
    for S1 in F:
        for x in X:
            S2 = S1.copy()
            if x in S2:
                S2.remove(x)
            else:
                S2.add(x)

            if len(S2) >= 2 and is_valid(S2):
                # S1 ^ S2 = {x}, so x must be in Q
                must_have.add(x)

    # Is must_have enough?
    # Let's check if there are any S1, S2 in F such that (S1 ^ S2) \cap must_have == empty.
    # This would mean we need more points.

    # Let's also find all d = S1 ^ S2 and find the minimum hitting set.
    # For small n, we can just list all d and find the hitting set.

