def count_extendable(n):
    extendable = set()
    # A cell x is extendable if there exists a valid K with |K| >= 2 and K \cup {x} is valid.
    # This is equivalent to saying there exist two cells y, z such that
    # {x, y, z} is king-independent.
    for i in range(1, 1 << (n*n)):
        subset = []
        for bit in range(n*n):
            if (i >> bit) & 1:
                subset.append((bit // n + 1, bit % n + 1))
        if is_king_independent(subset) and len(subset) >= 3:
            for x in subset:
                extendable.add(x)
    return len(extendable)

