def solve_n_fast(n):
    all_subsets = []
    for i in range(1, 1 << (n*n)):
        subset = []
        for bit in range(n*n):
            if (i >> bit) & 1:
                subset.append((bit // n + 1, bit % n + 1))
        if is_king_independent(subset):
            if len(subset) >= 2:
                all_subsets.append(set(subset))

    diffs = set()
    for i in range(len(all_subsets)):
        for j in range(i + 1, len(all_subsets)):
            diffs.add(frozenset(all_subsets[i] ^ all_subsets[j]))

    diff_list = [list(d) for d in diffs]

    mandatory = set()
    for d in diff_list:
        if len(d) == 1:
            mandatory.add(d[0])

    remaining_diffs = []
    for d in diff_list:
        if not any(cell in mandatory for cell in d):
            remaining_diffs.append(d)

    if not remaining_diffs:
        return len(mandatory)

    minimal_diffs = []
    for d1 in remaining_diffs:
        d1_set = set(d1)
        is_minimal = True
        for d2 in remaining_diffs:
            if d1_set != set(d2) and set(d2).issubset(d1_set):
                is_minimal = False
                break
        if is_minimal and d1 not in minimal_diffs:
            minimal_diffs.append(d1)

    min_extra = len(minimal_diffs)

    def backtrack_fast(idx, current_x):
        nonlocal min_extra
        if idx == len(minimal_diffs):
            min_extra = min(min_extra, len(current_x))
            return

        if any(cell in current_x for cell in minimal_diffs[idx]):
            backtrack_fast(idx + 1, current_x)
        else:
            if len(current_x) >= min_extra:
                return
            for cell in minimal_diffs[idx]:
                current_x.add(cell)
                backtrack_fast(idx + 1, current_x)
                current_x.remove(cell)

    backtrack_fast(0, set())
    return len(mandatory) + min_extra

