import itertools

def get_all_king_independent_sets(n):
    sets = []
    def backtrack(idx, current_set):
        if idx == n * n:
            if len(current_set) >= 2:
                sets.append(set(current_set))
            return

        # Option 1: Skip
        backtrack(idx + 1, current_set)

        # Option 2: Include
        r, c = divmod(idx, n)
        is_safe = True
        for pr, pc in current_set:
            if max(abs(r - pr), abs(c - pc)) < 2:
                is_safe = False
                break
        if is_safe:
            backtrack(idx + 1, current_set + [(r, c)])

