def find_min_hitting_set(diffs):
    # diffs is a list of frozensets
    # We want the smallest set Q such that Q \cap d != \emptyset for all d in diffs
    # This is the hitting set problem (equivalent to set cover).
    # Since the number of diffs and their sizes are small for small n,
    # we can use a simple recursive search or a greedy approach with backtracking.

    # First, find elements that must be in the hitting set (those that appear in a diff of size 1)
    must_have = set()
    remaining_diffs = []
    for d in diffs:
        if len(d) == 1:
            must_have.add(list(d)[0])
        else:
            remaining_diffs.append(d)

    # Remove diffs already covered by must_have
    remaining_diffs = [d for d in remaining_diffs if not (d & must_have)]

    if not remaining_diffs:
        return len(must_have)

    # Now we need to find the minimum hitting set for remaining_diffs
    # Use backtracking
    min_extra = float('inf')

    # Optimization: find the smallest diff and only try its elements
    def solve_recursive(current_diffs, current_count):
        nonlocal min_extra
        if not current_diffs:
            min_extra = min(min_extra, current_count)
            return

        if current_count >= min_extra:
            return

        # Choose the smallest diff to branch on
        smallest_diff = min(current_diffs, key=len)

        for element in smallest_diff:
            new_diffs = [d for d in current_diffs if element not in d]
            solve_recursive(new_diffs, current_count + 1)

    solve_recursive(remaining_diffs, 0)
    return len(must_have) + min_extra

def solve(n):
    cells = [(i, j) for i in range(n) for j in range(n)]
    independent_sets = []

    def backtrack(index, current_set):
        if index == len(cells):
            if len(current_set) >= 2:
                independent_sets.append(list(current_set))
            return

        # Option 1: Don't include cells[index]
        backtrack(index + 1, current_set)

        # Option 2: Include cells[index]
        if all(max(abs(cells[index][0] - c[0]), abs(cells[index][1] - c[1])) >= 2 for c in current_set):
            current_set.append(cells[index])
            backtrack(index + 1, current_set)
            current_set.pop()

    backtrack(0, [])

    diffs = set()
    for i in range(len(independent_sets)):
        for j in range(i + 1, len(independent_sets)):
            s1 = set(independent_sets[i])
            s2 = set(independent_sets[j])
            diff = s1.symmetric_difference(s2)
            if diff:
                diffs.add(frozenset(diff))

    return find_min_hitting_set(list(diffs))

